/// Makes the valuetypes of AbstractTest.idl known to the ORBs of the process, so
/// that values of derived types are read as themselves rather than
/// truncated (see `rustorb_core::idl::register_value`).
pub fn register_value_types() {
    ::rustorb_core::idl::register_value(abstract_test::Card::_info());
    ::rustorb_core::idl::register_supported(
        abstract_test::Named::REPOSITORY_ID,
        abstract_test::Card::REPOSITORY_ID,
        |h| {
            abstract_test::Card::from_handle(h.clone())
                .map(|v| Box::new(abstract_test::Named::from(v)) as Box<dyn ::std::any::Any + Send>)
        },
    );
}
